import time, random
def retry(fn, attempts=5, base_delay=0.1):
    for i in range(attempts):
        try:
            return fn()
        except Exception as e:
            if i == attempts - 1:
                raise
            sleep_for = base_delay * (2 ** i) * (1 + random.random())
            time.sleep(sleep_for)

