func readLines(path string) ([]string, error) {
    f, err := os.Open(path)
    if err != nil { return nil, err }
    defer f.Close()
    var out []string
    scanner := bufio.NewScanner(f)
    for scanner.Scan() {
        out = append(out, scanner.Text())
    }
    return out, scanner.Err()
}

